touch $T/stubs/caruca/__init__.py $T/stubs/caruca/ir/__init__.py $T/stubs/pash_annotations/__init__.py $T/stubs/pash_annotations/annotation_generation/__init__.py $T/stubs/pash_annotations/annotation_generation/annotation_generators/__init__.py
cat > $T/stubs/caruca/ir/syntax.py <<'EOF'
import enum
class Arity(enum.Enum):
    OPTIONAL=1; ZERO_OR_ONE=1; EXACTLY_ONE=2; EXACTLY_TWO=3; ZERO_OR_MORE=4; AT_LEAST_ONE=5; ONE_OR_MORE=5
class Node:
    def __init__(self, flag=None, alias=(), flag_followed_by_equals=False, choices=None, arity=Arity.OPTIONAL, dash_as_stdin=False, of=None, separator=None, **kw):
        self.kind=type(self).__name__; self.flag=flag; self.alias=list(alias); self.eq=flag_followed_by_equals
        self.choices=list(choices) if choices else None; self.arity=arity; self.of=of; self.separator=separator
class Flag(Node):
    def __init__(self, flag, alias=()): super().__init__(flag=flag, alias=alias)
for n in "Path Integer Int Number Pid Duration String Other User Format Selection List Regex Glob Separator Delimiter Char Range Size Permission OwnerGroup Group Signal Variable Command Hostname Filesystem Date DateTime DateFormat TimeStyle Expression PrintfFormat SprintfFormat Geometry SecurityContext SecurityRange SecurityRole SecurityType".split():
    globals()[n]=type(n,(Node,),{})
SyntaxSpecification=list
EOF
