cd $T && echo hi > a && mkdir d && PYTHONPATH=$T/stubs:/home/tirandagan.guest/naive-arm/output:/home/tirandagan.guest/naive-arm/output/annotation python3 - <<'EOF'
import json, re, subprocess, importlib
from cp import cp_syntax_spec
from InputOutputInfoGeneratorCp import InputOutputInfoGeneratorCp as IO
from ParallelizabilityInfoGeneratorCp import ParallelizabilityInfoGeneratorCp as PAR

def run(args):
    p = subprocess.run(["cp"]+args+["a","d"], capture_output=True, text=True)
    return p.returncode, p.stderr.strip().split("\n")[0]

bad = []
spec_spellings=set()
for syn in cp_syntax_spec:
    for n in syn[0]:
        sp=[n.flag]+n.alias
        spec_spellings.update(sp)
        for s in sp:
            if n.kind=="Flag":
                rc,err=run([s])
                if "invalid option" in err or "unrecognized" in err or "requires an argument" in err: bad.append((s,err))
            else:
                choices = n.choices or (n.of.choices if n.of else None)
                vals = choices or ({"Path":["d"],"String":[".bak"],"SecurityContext":["u:r:t:s0"]}[n.kind])
                for v in vals:
                    for form in ([f"{s}={v}"] if s.startswith("--") else [f"{s}{v}", s, v][0:1]+[[s,v]]):
                        args = form if isinstance(form,list) else [form]
                        rc,err=run(args)
                        if "invalid" in err or "ambiguous" in err or "unrecognized" in err or "requires an argument" in err or "missing" in err:
                            bad.append((args,err))
                if n.kind=="List":  # combined list
                    rc,err=run([f"{s}={','.join(choices[:3])}"])
                    if rc!=0: bad.append((s,err))
                if n.kind=="Selection" and n.eq:  # bogus value should be rejected
                    rc,err=run([f"{s}=bogus"])
                    if "invalid" not in err: bad.append((s+"=bogus accepted",err))
print("binary rejects from spec:", bad)

help_txt = subprocess.run(["cp","--help"],capture_output=True,text=True).stdout
help_spellings=set(re.findall(r"(?<![\w-])(--?[A-Za-z][\w-]*)", help_txt.split("ATTR_LIST is")[0]))
help_spellings -= {"-dR"}
print("in help but not spec:", help_spellings-spec_spellings)
print("in spec but not help:", spec_spellings-help_spellings)

j=json.load(open("/home/tirandagan.guest/naive-arm/output/annotation/cp.json"))
json_sp=set()
for e in j["flag"]: json_sp.update([e] if isinstance(e,str) else e)
for e in j["option"]: json_sp.update(x for x in e[:-1])
print("json vs spec diff:", json_sp ^ spec_spellings)
# values that take args in json must be value nodes in spec and vice versa
spec_valued={s for syn in cp_syntax_spec for n in syn[0] if n.kind!="Flag" for s in [n.flag]+n.alias}
json_valued={x for e in j["option"] for x in e[:-1]}
print("valued mismatch:", spec_valued ^ json_valued)

for flags,ops in [([],["s","t"]),(["-R","-v"],["s1","s2","dir"]),(["-t","-i"],["s1","s2"]),(["--debug"],["x","y"])]:
    g=IO(flags,ops); g.generate_info(); print(flags,ops,"->",g.log)
    p=PAR(flags,ops); p.generate_info(); print("  parallelizers:",p.parallelizers)
try:
    g=IO([],["only"]); g.generate_info()
except Exception as e: print("1 operand ->", e)
EOF
